import {Screen as Material} from "./1Adding Interactivity/0RespondingToEvents"
import Root from "./1Adding Interactivity/2StateasSnapshot"
import Sub from "./subReLearn"
import "./ReLearn.css"
import { useState } from "react"

export default function () {
  const [val, setVal] = useState("")
  return (
    <>
    <select value={val} onChange={(e) => {setVal(e.target.value)}}>
      <option value="1"/>
      <option value="wow"/>
      <option value="real"/>
    </select>
    <p style={{}}>  
      {val}
    </p>

    <select>
          <option value="1">1</option>
          <option value="2">2</option>
          <option value="3">3</option>
      </select>
    </>
  );
}



// http://localhost:3000
